draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // two characters
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2-20);
  ctx.lineTo(W/4, H/2-50);
  ctx.lineTo(W/4-20, H/2-30);
  ctx.lineTo(W/4, H/2-20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2+20);
  ctx.lineTo(W/4, H/2+50);
  ctx.lineTo(W/4-20, H/2+30);
  ctx.lineTo(W/4, H/2+20);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W-W/4, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W-W/4, H/2-20);
  ctx.lineTo(W-W/4, H/2-50);
  ctx.lineTo(W-W/4+20, H/2-30);
  ctx.lineTo(W-W/4, H/2-20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W-W/4, H/2+20);
  ctx.lineTo(W-W/4, H/2+50);
  ctx.lineTo(W-W/4+20, H/2+30);
  ctx.lineTo(W-W/4, H/2+20);
  ctx.stroke();

  // conflict
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-50+50*Math.sin(t));
  ctx.lineTo(W/2, H/2+50-50*Math.sin(t));
  ctx.stroke();

  // navigation
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.setLineDash([10, 10]);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.restore();
}
